async function getLinkedIssues(owner, repo, prNumber) {
  const query = `query GetLinkedIssues($owner: String!, $repo: String!, $prNumber: Int!) {
    repository(owner: $owner, name: $repo) {
      pullRequest(number: $prNumber) {
        closingIssuesReferences(first: 10) {
          nodes {
            number
            labels(first: 10) {
              nodes {
                name
              }
            }
          }
        }
      }
    }
  }`;

  const variables = {
    owner: owner,
    repo: repo,
    prNumber: prNumber,
  };

  const result = await github.graphql(query, variables);
  return result.repository.pullRequest.closingIssuesReferences.nodes;
}

const pr = context.payload.pull_request;
const linkedIssues = await getLinkedIssues(
  context.repo.owner,
  context.repo.repo,
  pr.number
);

const labelsToAdd = new Set();
for (const issue of linkedIssues) {
  if (issue.labels && issue.labels.nodes) {
    for (const label of issue.labels.nodes) {
      labelsToAdd.add(label.name);
    }
  }
}

if (labelsToAdd.size) {
  await github.rest.issues.addLabels({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: pr.number,
    labels: Array.from(labelsToAdd),
  });
}

let labels = [];

if (context.payload.pull_request) {
  labels = context.payload.pull_request.labels;
} else {
  try {
    const sha = '${{ needs.changes.outputs.commit-sha }}';
    console.log('sha', sha);
    const { data: prs } = await github.rest.repos.listPullRequestsAssociatedWithCommit({
      owner: context.repo.owner,
      repo: context.repo.repo,
      commit_sha: sha
    });

    if (prs.length === 0) {
      core.setOutput('run-e2e', false);
      console.log(`No pull requests found for commit SHA ${sha}`);
      return;
    }

    const pr = prs[0];
    console.log(`PR number: ${pr.number}`);
    console.log(`PR title: ${pr.title}`);
    console.log(`PR state: ${pr.state}`);
    console.log(`PR URL: ${pr.html_url}`);

    labels = pr.labels;
  }
  catch (e) {
    core.setOutput('run-e2e', false);
    console.log(e);
  }
}

const labelFound = labels.map(l => l.name).includes('ready-for-e2e');
console.log('Found the label?', labelFound);
core.setOutput('run-e2e', labelFound);

let allArtifacts = await github.rest.actions.listWorkflowRunArtifacts({
   owner: context.repo.owner,
   repo: context.repo.repo,
   run_id: context.payload.workflow_run.id,
});

let matchArtifact = allArtifacts.data.artifacts.filter((artifact) => {
  return artifact.name == "context.json"
})[0];

let download = await github.rest.actions.downloadArtifact({
   owner: context.repo.owner,
   repo: context.repo.repo,
   artifact_id: matchArtifact.id,
   archive_format: 'zip',
});

let fs = require('fs');
fs.writeFileSync(`${process.env.GITHUB_WORKSPACE}/context.zip`, Buffer.from(download.data));

let fs = require('fs');
let data = fs.readFileSync('./context.json');
return JSON.parse(data);

async function getPullRequestId() {
  const pull_number = ${{ needs.download-context.outputs.pr_number }}; 
  const pullRequest = await github.rest.pulls.get({
    owner: context.repo.owner,
    repo: context.repo.repo,
    pull_number,
  });
  if (!pullRequest.data.node_id) throw new Error(`pullRequestId no found for '${pull_number}'`);
  return pullRequest.data.node_id;
}
const query = `
  mutation($id: ID!) {
    convertPullRequestToDraft(input: { pullRequestId: $id }) {
      pullRequest {
        id
        number
        isDraft
      }
    }
  }
`;
const pullRequestId = await getPullRequestId();
const variables = {
  id: pullRequestId,
}
const response = await github.graphql(query, variables)
if (!response.convertPullRequestToDraft) {
  throw new Error("Failed to convert pull request to draft");
}
console.info("Pull request successfully converted to draft.");
console.info(`Draft conversion response: ${JSON.stringify(response, null, 2)}`);

try {
  const response = await github.rest.actions.createWorkflowDispatch({
    owner: context.repo.owner,
    repo: 'docker',
    workflow_id: 'create-release.yaml',
    ref: 'main',
    inputs: {
      "RELEASE_TAG": process.env.RELEASE_TAG
    },
  });

  console.log(response);
} catch (error) {
  console.error(error);
  core.setFailed(error.message);
}
